test('vatSummary aggregates multiple lines with same rate', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 1 },
      { sku: 'DES-HOUR', qty: 2 },
    ],
  });
  const issued = issueInvoice(inv.value, []);

  const result = vatSummary([issued.value]);

  assert.equal(result.value.length, 1);
  const line1 = issued.value.lines[0];
  const line2 = issued.value.lines[1];
  const expectedBase = (lineTotal(line1) - lineDiscount(line1)) + (lineTotal(line2) - lineDiscount(line2));
  const expectedVat = lineVAT(line1) + lineVAT(line2);

  assert.equal(result.value[0].base, expectedBase);
  assert.equal(result.value[0].vat, expectedVat);
});

