test('lateFee across month boundary', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-25',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(inv.value, []);
  const due = balanceDue(issued.value);

  const fee = lateFee(issued.value, '2026-11-15');

  const expected = Math.round(due * 0.0004 * 7);
  assert.equal(fee, expected);
});

test('lateFee scales linearly with days', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(inv.value, []);

  const fee5 = lateFee(issued.value, '2026-10-20');
  const fee10 = lateFee(issued.value, '2026-10-25');

  assert(fee10 > fee5);
  const ratio = fee10 / fee5;
  assert(ratio > 1.9 && ratio <= 2);
});

test('lateFee with voucher applied reduces basis', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(inv.value, []);
  const totals = invoiceTotals(issued.value);
  const withVoucher = { ...issued.value, voucher: { code: 'SAVE10', amount: Math.floor(totals.total / 4) } };

  const feeWithout = lateFee(issued.value, '2026-10-20');
  const feeWith = lateFee(withVoucher, '2026-10-20');

  assert(feeWith < feeWithout);
});

